-- 6.5.7.1
DELETE FROM inspection_item_revisions WHERE item_id = '6.5.7.1' AND introduction_type != 'revision';
INSERT INTO inspection_item_revisions (item_id, effective_date, expiry_date, introduction_type, description) VALUES ('6.5.7.1', '2022-03-02', NULL, 'current', '6.5.7.1 카가 6.5.6.1에 따른 최고 위치에 있을 때 표 2에 따른 피난공간을 수용할 수 있는 유효 구역이 1개 이상 카 지붕에 있어야 한다. 표 2의 유형 2에 따른 피난공간이 카 지붕의 고정된 부품과 닿는 경우, 피난공간 모서리 하단부의 한쪽 면은 카 지붕에 고정된 부품을 포함하기 위해 폭 0.1 m, 높이 0.3 m까지의 공간을 줄일 수 있다.(그림 4 참조) 점검 등 유지관리 업무 수행을 위해 두 명 이상의 사람이 카 지붕 위에 있어야 하는 경우, 피난공간은 추가되는 사람마다 각각 제공되어야 한다. 피난공간이 두 개 이상인 경우, 각 피난공간들은 같은 유형이어야 하고, 서로 간섭되지 않아야 한다. 피난공간의 허용 가능 인원 및 자세 유형(표 2)이 명확하게 표시된 표지가 카 지붕에 있어야 하고, 그 표지는 승강장에서 카 지붕으로 출입하는 경로에서 읽을 수 있는 위치에 있어야 한다. 균형추가 사용된 경우, 균형추 칸막이(6.5.5.1 참조)표면 또는 주위에 카가 최상층 승강장에 있을 때 카 상부 피난공간의 크기를 유지하기 위한 균형추와 균형추 완충기 사이의 최대 허용 틈새가 명시된 표지가 부착되어 있어야 한다. <2019년 3월 28일 이후 건축허가분부터 적용>');
